urlset:
{% for page in pages %}

  {{ request.url_root.rstrip("/") }}{{ page.canonical_path }}
  {% if page.modified %}{{ page.modified[:10] }}{% endif %}

{% endfor %}
{% for post in posts %}

  {{ request.url_root.rstrip("/") }}{{ post.canonical_path }}
  {% if post.modified %}{{ post.modified[:10] }}{% endif %}

{% endfor %}
